/** Operation-count contracts for legacy writer semantic indexes and pending rows. */
class LmdbLegacyIngestionComplexityTest {

	private static final SimpleValueFactory VALUES = SimpleValueFactory.getInstance();
	private static final IRI LABEL = VALUES.createIRI("urn:legacy:label");
	private static final IRI CONTEXT = VALUES.createIRI("urn:legacy:context");
	private static final int VALUES_PER_WRITER = 12;
	private static final int STATEMENT_GROUPS = 16;
	private static final int PENDING_CACHE_SEED_ROWS = 2_000;

	@TempDir
	Path directory;
	private SailRepository repository;

	@AfterEach
	void close() {
		if (repository != null) {
			repository.shutDown();
		}
	}

	@Test
	void writerLookupStopsAfterTheFirstAuthoritativeCaseEquivalentAlias() throws Exception {
		openStore("v2-610-language-aliases.zip", 0);
		ValueStore values = (ValueStore) repository.getValueFactory();
		backingStore().enableMultiThreading = false;
		AtomicInteger validations = new AtomicInteger();
		try (var sink = backingStore().getExplicitSailSource().sink(IsolationLevels.NONE)) {
			sink.approve(VALUES.createIRI("urn:complexity:seed"), LABEL, VALUES.createLiteral("seed"), CONTEXT);
			values.storeValue(VALUES.createLiteral("prime index", "en"));
			values.setLegacySemanticLookupObserver(id -> validations.incrementAndGet());
			try {
				for (int iteration = 0; iteration < VALUES_PER_WRITER; iteration++) {
					// The smallest supported ID cache has four ways: five distinct keys evict the previous lookup.
					for (int chaff = 0; chaff < 5; chaff++) {
						values.storeValue(VALUES.createLiteral("chaff " + iteration + ":" + chaff));
					}
					Literal alias = VALUES.createLiteral("language value", iteration % 2 == 0 ? "eN" : "En");
					long id = values.getId(alias);
					assertThat(id).isNotEqualTo(LmdbValue.UNKNOWN_ID);
					assertThat(values.getValue(id)).isEqualTo(alias);
				}
			} finally {
				values.setLegacySemanticLookupObserver(null);
			}
			sink.flush();
		}
		assertThat(validations).as("one authoritative alias suffices; there is no smallest-ID RDF contract")
				.hasValue(VALUES_PER_WRITER);
	}

	@Test
	void legacyDictionaryOwnersAreScannedOncePerWriterGeneration() throws Exception {
		openStore("v2-610-language-aliases.zip", 0);
		LmdbSailStore backing = backingStore();
		ValueStore values = (ValueStore) repository.getValueFactory();
		ScanMetrics dictionaryScans = new ScanMetrics();

		try (var sink = backing.getExplicitSailSource().sink(IsolationLevels.NONE)) {
			// Start the native writer without introducing a language-bearing value into the measured lookup phase.
			sink.approve(VALUES.createIRI("urn:complexity:seed"), LABEL, VALUES.createLiteral("seed"), CONTEXT);
			values.setLegacySemanticScanObserver(dictionaryScans);
			for (int index = 0; index < VALUES_PER_WRITER; index++) {
				Literal literal = VALUES.createLiteral("new language value " + index, "en");
				assertThat(values.storeValue(literal)).isNotEqualTo(LmdbValue.UNKNOWN_ID);
			}
			values.setLegacySemanticScanObserver(null);
			sink.flush();
		}

		assertThat(dictionaryScans.invocations())
				.as("distinct language values should share one legacy dictionary-owner pass "
						+ "(passes=%d, visited records=%d)", dictionaryScans.invocations(),
						dictionaryScans.visitedRecords())
				.isLessThanOrEqualTo(1);
		assertThat(dictionaryScans.visitedRecords())
				.as("the dictionary-owner pass must actually inspect the legacy dictionary")
				.isPositive();
	}

	@Test
	void nestedTermOwnersAreScannedOncePerWriterGeneration() throws Exception {
		openStore("v2-610-language-aliases.zip", 0);
		LmdbSailStore backing = backingStore();
		ValueStore values = (ValueStore) repository.getValueFactory();
		ScanMetrics termScans = new ScanMetrics();
		List<Literal> literals = new ArrayList<>();
		List<Long> innerIds = new ArrayList<>();
		List<Long> outerIds = new ArrayList<>();
		Resource termSubject = VALUES.createIRI("urn:legacy:inner");

		try (var sink = backing.getExplicitSailSource().sink(IsolationLevels.NONE)) {
			sink.approve(VALUES.createIRI("urn:complexity:seed"), LABEL, VALUES.createLiteral("seed"), CONTEXT);
			for (int index = 0; index < VALUES_PER_WRITER; index++) {
				Literal literal = VALUES.createLiteral("nested language value " + index, "en");
				literals.add(literal);
				assertThat(values.storeValue(literal)).isNotEqualTo(LmdbValue.UNKNOWN_ID);
			}
			values.setLegacySemanticScanObserver(termScans);
			for (Literal literal : literals) {
				TripleTerm inner = VALUES.createTripleTerm(termSubject, LABEL, literal);
				innerIds.add(values.storeValue(inner));
				TripleTerm outer = VALUES.createTripleTerm(termSubject, LABEL, inner);
				outerIds.add(values.storeValue(outer));
			}
			values.setLegacySemanticScanObserver(null);
			sink.flush();
		}
		assertThat(termScans.invocations())
				.as("nested language-bearing terms should share one term-owner pass "
						+ "(passes=%d, visited records=%d)", termScans.invocations(), termScans.visitedRecords())
				.isLessThanOrEqualTo(1);
		assertThat(termScans.visitedRecords())
				.as("the term-owner pass must actually inspect the legacy term indexes")
				.isPositive();

		for (int index = 0; index < VALUES_PER_WRITER; index++) {
			Literal alias = VALUES.createLiteral("nested language value " + index, "EN");
			TripleTerm innerAlias = VALUES.createTripleTerm(termSubject, LABEL, alias);
			TripleTerm outerAlias = VALUES.createTripleTerm(termSubject, LABEL, innerAlias);
			assertThat(values.getId(alias)).isNotEqualTo(LmdbValue.UNKNOWN_ID);
			assertThat(values.getId(innerAlias)).isEqualTo(innerIds.get(index));
			assertThat(values.getId(outerAlias)).isEqualTo(outerIds.get(index));
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { true, false })
	void pendingCacheSemanticScansStayBoundedAndPreserveStatementFields(boolean inferred) throws Exception {
		openStore("v2-empty-inline-false.zip", 128L * 1024);
		LmdbSailStore backing = backingStore();
		TripleStore tripleStore = backing.getTripleStore();
		ValueStore values = (ValueStore) repository.getValueFactory();
		ScanMetrics pendingScans = new ScanMetrics();
		// Run synchronously so each observed pending-cache traversal belongs to the operation that requested it.
		backing.enableMultiThreading = false;
		SailSource source = inferred ? backing.getInferredSailSource() : backing.getExplicitSailSource();
		int expectedNewRows = STATEMENT_GROUPS * 3;

		try (var sink = source.sink(IsolationLevels.NONE)) {
			for (int index = 0; index < PENDING_CACHE_SEED_ROWS; index++) {
				sink.approve(VALUES.createIRI("urn:complexity:filler:" + index), LABEL,
						VALUES.createLiteral("pending cache filler " + index), CONTEXT);
			}
			assertThat(tripleStore.hasPendingRecordCache())
					.as("the small configured map must overflow into the real pending record cache")
					.isTrue();
			tripleStore.setLegacyPendingScanObserver(pendingScans);
			for (int index = 0; index < STATEMENT_GROUPS; index++) {
				IRI subject = VALUES.createIRI("urn:complexity:subject:" + index);
				Literal lower = VALUES.createLiteral("pending language value " + index, "en");
				Literal upper = VALUES.createLiteral("pending language value " + index, "EN");
				TripleTerm innerLower = VALUES.createTripleTerm(subject, LABEL, lower);
				TripleTerm innerUpper = VALUES.createTripleTerm(subject, LABEL, upper);
				TripleTerm outerLower = VALUES.createTripleTerm(subject, LABEL, innerLower);
				TripleTerm outerUpper = VALUES.createTripleTerm(subject, LABEL, innerUpper);

				sink.approve(subject, LABEL, lower, CONTEXT);
				sink.approve(subject, LABEL, upper, CONTEXT);
				sink.approve(subject, LABEL, innerLower, CONTEXT);
				sink.approve(subject, LABEL, innerUpper, CONTEXT);
				sink.approve(subject, LABEL, outerLower, CONTEXT);
				sink.approve(subject, LABEL, outerUpper, CONTEXT);
			}
			sink.flush();
		}

		long maximumPendingBatchesPerPass = (PENDING_CACHE_SEED_ROWS + expectedNewRows + 255L) / 256L;
		assertThat(pendingScans.invocations())
				.as("one writer generation should scan each pending database at most once in bounded batches "
						+ "(batches=%d, visited records=%d)", pendingScans.invocations(), pendingScans.visitedRecords())
				.isLessThanOrEqualTo(2 * maximumPendingBatchesPerPass + 2);
		assertThat(pendingScans.visitedRecords())
				.as("pending rows should be visited linearly, not once per added alias")
				.isLessThanOrEqualTo(2L * (PENDING_CACHE_SEED_ROWS + expectedNewRows));

		try (var connection = repository.getConnection()) {
			assertThat(QueryResults.asList(connection.getStatements(null, LABEL, null, true, CONTEXT)))
					.hasSize(PENDING_CACHE_SEED_ROWS + expectedNewRows);
			for (int index = 0; index < STATEMENT_GROUPS; index++) {
				IRI subject = VALUES.createIRI("urn:complexity:subject:" + index);
				Literal alias = VALUES.createLiteral("pending language value " + index, "eN");
				TripleTerm innerAlias = VALUES.createTripleTerm(subject, LABEL, alias);
				TripleTerm outerAlias = VALUES.createTripleTerm(subject, LABEL, innerAlias);
				assertThat(connection.hasStatement(subject, LABEL, alias, true, CONTEXT)).isTrue();
				assertThat(connection.hasStatement(subject, LABEL, innerAlias, true, CONTEXT)).isTrue();
				assertThat(connection.hasStatement(subject, LABEL, outerAlias, true, CONTEXT)).isTrue();
				assertThat(connection.hasStatement(subject,
						VALUES.createIRI("urn:complexity:other-predicate"), alias, true, CONTEXT)).isFalse();
				assertThat(connection.hasStatement(subject, LABEL, alias, true,
						VALUES.createIRI("urn:complexity:other-context"))).isFalse();
			}
		}
	}

	private void openStore(String fixture, long tripleDbSize) throws Exception {
		LmdbCompatibilityFixtures.extract(fixture, directory);
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc")
				.setTripleTermIndexes("spoc,cspo")
				.setInlineLiterals(false)
				.setBulkOperationSize(0)
				.setValueIDCacheSize(1);
		if (tripleDbSize > 0) {
			config.setTripleDBSize(tripleDbSize);
		}
		repository = new SailRepository(new LmdbStore(directory.toFile(), config));
		repository.init();
	}

	private LmdbSailStore backingStore() {
		return ((LmdbStore) repository.getSail()).getBackingStore();
	}

	private static final class ScanMetrics implements LongConsumer {
		private final LongAdder invocations = new LongAdder();
		private final LongAdder visitedRecords = new LongAdder();

		@Override
		public void accept(long records) {
			invocations.increment();
			visitedRecords.add(records);
		}

		long invocations() {
			return invocations.sum();
		}

		long visitedRecords() {
			return visitedRecords.sum();
		}
	}
}
